@startuml
class User {
  + name : string
}
class Subscriber extends User {
  + card : Card
}
class Card {
  + credit : float
}
class Movie {
  + title : string
}
class Order {
  + date : date
}
class Rental {
  + date : date
}
class Backorder {
  + date : date
}

User "1" -- "*" Order : places
Subscriber "1" -- "1" Card : has
Subscriber "1" -- "*" Rental : performs
Rental "*" -- "1" Movie : involves
Order "*" -- "1" Movie : contains
Backorder "*" -- "1" Movie : is for
@enduml

